SET @kurs_id = (SELECT id FROM courses WHERE slug = 'ruby');

-- ============================================================
-- LEKCE 1–20 + ZÁVĚREČNÝ KVÍZ
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Úvod do Ruby', '<h2>Co je Ruby?</h2><p>Ruby je dynamický, objektově orientovaný programovací jazyk, který vytvořil <strong>Yukihiro "Matz" Matsumoto</strong> v roce 1995. Filozofie Ruby je <em>"pravděpodobně nejlepší způsob, jak udělat programátory šťastnými"</em>. Ruby klade důraz na čitelnost, produktivitu a princip <strong>least surprise</strong> — jazyk by se měl chovat tak, jak očekáváš.</p><h2>IRB — interaktivní konzole</h2><p><code>irb</code> (Interactive Ruby) je REPL nástroj, který ti umožňuje psát Ruby kód a okamžitě vidět výsledky. Spustíš ho příkazem <code>irb</code> v terminálu.</p><pre><code># Spuštění IRB v terminálu\n# $ irb\n\nirb(main):001:0> 2 + 3\n=> 5\nirb(main):002:0> "Ahoj" + " svete"\n=> "Ahoj svete"\nirb(main):003:0> [1, 2, 3].map { |x| x * 2 }\n=> [2, 4, 6]</code></pre><h2>Vše je objekt</h2><p>V Ruby je <strong>všechno objekt</strong> — čísla, řetězce, dokonce i <code>nil</code> a <code>true/false</code>. Žádné primitivní typy neexistují. Každý objekt má metody, které můžeš volat.</p><pre><code># Čísla jsou objekty\n5.class        #=> Integer\n3.14.class    #=> Float\n\n# Řetězce jsou objekty\n"hello".class  #=> String\n"hello".upcase #=> "HELLO"\n"hello".length #=> 5\n\n# Dokonce nil je objekt\nnil.class     #=> NilClass\nnil.nil?      #=> true\nnil.to_s     #=> ""\n\n# Základní výstup a vstup\nputs "Ahoj, svete!"   # vypíše s novým řádkem\nprint "Zadej jmeno: "  # vypíše bez nového řádku\njmeno = gets.chomp     # přečte vstup a odstraní \\n</code></pre><h2>Konvence Ruby</h2><p>Ruby používá <strong>snake_case</strong> pro metody a proměnné, <strong>CamelCase</strong> pro třídy a moduly. Metody s otazníkem (<code>nil?</code>) vrací boolean, vykřičníkem (<code>save!</code>) vyhazují výjimky.</p>', 'lesson', 1, 15, 12),

(@kurs_id, 'Proměnné a typy', '<h2>Proměnné v Ruby</h2><p>Ruby je dynamicky typovaný jazyk — typ proměnné se určuje za běhu a může se měnit. Proměnné deklaruješ prostým přiřazením, žádné klíčové slovo <code>var</code> či <code>let</code> není potřeba.</p><pre><code># Lokální proměnné\njmeno = "Karel"\nvek = 25\npi = 3.14159\n\n# Konstanty — velkými písmeny\nPI = 3.14159\nMAX_POCET = 100\n\n# Paralelní přiřazení\na, b, c = 1, 2, 3\nx, y = y, x   # prohození hodnot</code></pre><h2>Základní typy</h2><p>Ruby má bohatou sadu vestavěných typů. Každý typ je plnohodnotný objekt se svými metodami.</p><pre><code># String — řetězec\njmeno = "Karel"\npozdrav = "Ahoj, #{jmeno}!"  # interpolace\ndelka = jmeno.length        # 5\nopacny = jmeno.reverse       # "leraK"\ncislo = "42".to_i           # 42\n\n# Integer — celé číslo\na = 42\nb = 0xff        # hex\nc = 0b1010      # binární\nd = 7.times { |i| puts i }  # iterace\n\n# Float — desetinné číslo\npi = 3.14\nzaokrouhleno = pi.round(1)  # 3.1\n\n# Array — pole\novoce = ["jablko", "hruska", "banan"]\novoce.push("meloun")\novoce << "tresen"     # operátor <<\nprvni = ovoce[0]      # "jablko"\n\n# Hash — slovník / asociativní pole\nosoba = { jmeno: "Karel", vek: 25 }\nputs osoba[:jmeno]    # "Karel"\nosoba[:mesto] = "Praha"\n\n# Symbol — neměnný identifikátor\nstatus = :aktivni\nstatus == :aktivni   # true\n\n# nil — absence hodnoty\nx = nil\nx.nil?              # true\nx || "vychozi"      # "vychozi"</code></pre>', 'lesson', 2, 15, 14),

(@kurs_id, 'Řízení toku', '<h2>Podmínky if/elsif/else</h2><p>Ruby nabízí klasické podmíněné příkazy, ale s vlastními syntaktickými vylepšeními. Podmínky mohou stát i za příkazem (modifier form).</p><pre><code># Klasický if/elsif/else\nvek = 20\n\nif vek >= 18\n  puts "Dospely"\nelsif vek >= 15\n  puts "Teenager"\nelse\n  puts "Dite"\nend\n\n# Modifier form — za příkazem\nputs "Dospely" if vek >= 18\n\n# unless — opak if\nunless zablokovan\n  puts "Pristup povolen"\nend\n# ekvivalent: if !zablokovan</code></pre><h2>case/when</h2><p>Příkaz <code>case</code> nahrazuje dlouhé řetězce <code>if/elsif</code>. Porovnává pomocí operátoru <code>===</code>.</p><pre><code>hodnoceni = "B"\n\ncase hodnoceni\nwhen "A"\n  puts "Vynikajici"\nwhen "B"\n  puts "Dobry"\nwhen "C"\n  puts "Prumer"\nelse\n  puts "Nedostatecny"\nend\n\n# Case s rozsahem\nskore = 85\ncase skore\nwhen 90..100 then puts "A"\nwhen 80..89  then puts "B"\nwhen 70..79  then puts "C"\nelse              puts "F"\nend</code></pre><h2>Ternární operátor</h2><p>Ternární operátor je zkrácený zápis jednoduché podmínky: <code>podminka ? hodnota_if : hodnota_else</code>.</p><pre><code># Ternární operátor\nvek = 20\nstatus = vek >= 18 ? "dospely" : "dite"\nputs status  # "dospely"\n\n# Porovnání s if/else ekvivalentem\nif vek >= 18\n  status = "dospely"\nelse\n  status = "dite"\nend</code></pre>', 'lesson', 3, 15, 12),

(@kurs_id, 'Metody a bloky', '<h2>Definice metod</h2><p>Metody v Ruby definuješ klíčovým slovem <code>def</code>. Metoda vždy vrací výsledek posledního vyhodnoceného výrazu — není potřeba explicitní <code>return</code>.</p><pre><code># Jednoduchá metoda\ndef pozdrav(jmeno)\n  "Ahoj, #{jmeno}!"\nend\n\nputs pozdrav("Karel")  # "Ahoj, Karel!"\n\n# Výchozí hodnoty parametrů\ndef mocnina(zaklad, exponent = 2)\n  zaklad ** exponent\nend\n\nputs mocnina(3)     # 9 (3^2)\nputs mocnina(2, 10) # 1024 (2^10)\n\n# Parametry s klíčovým slovem (keyword arguments)\ndef vytvor_uzivatele(jmeno:, vek:, mesto: "Praha")\n  "#{jmeno}, #{vek} let, #{mesto}"\nend\n\nputs vytvor_uzivatele(jmeno: "Eva", vek: 30)</code></pre><h2>Bloky, Proc a Lambda</h2><p>Blok je anonymní kus kódu, který předáváš metodě. <code>yield</code> volá blok uvnitř metody. Blok můžeš převést na objekt pomocí <code>Proc</code> nebo <code>lambda</code>.</p><pre><code># yield — volání bloku\ndef dvakrat\n  puts "Pred blokem"\n  yield\n  yield\n  puts "Po bloku"\nend\n\ndvakrat { puts "Ahoj!" }\n# Pred blokem\n# Ahoj!\n# Ahoj!\n# Po bloku\n\n# Blok s parametry\ndef mapa(pole)\n  result = []\n  pole.each { |prvek| result << yield(prvek) }\n  result\nend\n\nmapa([1, 2, 3]) { |x| x * x }  # [1, 4, 9]\n\n# Proc — blok jako objekt\ndvojnasobek = Proc.new { |x| x * 2 }\n[1, 2, 3].map(&dvojnasobek)  # [2, 4, 6]\n\n# Lambda — striktní arita\ncubed = ->(x) { x ** 3 }\ncubed.call(3)  # 27\n\n# Rozdíl: lambda kontroluje počet argumentů, Proc ne\n# lambda return vrací z bloku, Proc return vrací z obklopující metody</code></pre><h2>Operátor &amp;</h2><p>Operátor <code>&amp;</code> převádí symbol na Proc a naopak. Umožňuje stručný zápis běžných operací.</p><pre><code># Symbol to Proc\n["ahoj", "svete"].map(&:upcase)  # ["AHOJ", "SVETE"]\n[1, 2, 3].map(&:to_s)           # ["1", "2", "3"]\n\n# Blok to Proc\ndef spust(&blok)\n  blok.call\nend\n\nspust { puts "Bezim!" }</code></pre>', 'lesson', 4, 15, 16),

(@kurs_id, 'Třídy a OOP', '<h2>Třída v Ruby</h2><p>Ruby je čistě objektově orientovaný jazyk. Třídy definuješ klíčovým slovem <code>class</code>. Konstruktor se jmenuje <code>initialize</code>. Instanční proměnné začínají <code>@</code>, třídní <code>@@</code>.</p><pre><code>class Zviratko\n  # Konstruktor\n  def initialize(jmeno, zvuk)\n    @jmeno = jmeno\n    @zvuk = zvuk\n  end\n  \n  # Atributy — čtení i zápis\n  attr_accessor :jmeno\n  attr_reader :zvuk\n  attr_writer :vek\n  \n  # Instanční metoda\n  def mluv\n    "#{@jmeno} rika: #{@zvuk}!"\n  end\n  \n  # Třídní metoda\n  def self.popis\n    "Zviratko je zakladni trida"\n  end\nend\n\nkocka = Zviratko.new("Micka", "mnau")\nputs kocka.mluv       # "Micka rika: mnau!"\nputs kocka.jmeno     # "Micka"\nkocka.jmeno = "Cesmin"\nputs Zviratko.popis  # "Zviratko je zakladni trida"</code></pre><h2>Dědičnost</h2><p>Ruby podporuje <strong>jednoduchou dědičnost</strong> operátorem <code>&lt;</code>. Podtřída dědí metody a může je přepisovat (<code>super</code> volá rodičovskou metodu).</p><pre><code>class Pes < Zviratko\n  def initialize(jmeno)\n    super(jmeno, "haf")\n  end\n  \n  def aportuj(vec)\n    "#{@jmeno} prinasi #{vec}"\n  end\nend\n\nrex = Pes.new("Rex")\nputs rex.mluv      # "Rex rika: haf!"\nputs rex.aportuj("mic")  # "Rex prinasi mic"</code></pre><h2>Moduly a mixiny</h2><p>Modul je kolekce metod, kterou nemůžeš instanciovat. Slouží jako <strong>mixin</strong> — přidává funkčnost třídám pomocí <code>include</code> (instanční metody) a <code>extend</code> (třídní metody).</p><pre><code>module Zvukovy\n  def zvukově(sila)\n    "#{@zvuk} " * sila\n  end\nend\n\nclass Pes < Zviratko\n  include Zvukovy\n  \n  def initialize(jmeno)\n    super(jmeno, "haf")\n  end\nend\n\nrex = Pes.new("Rex")\nputs rex.zvukově(3)  # "haf haf haf "</code></pre>', 'lesson', 5, 15, 16),

(@kurs_id, 'Kolekce a Enumerable', '<h2>Pole a iterace</h2><p>Pole (Array) je nejčastější kolekce v Ruby. Nabízí bohatou sadu metod pro iteraci, transformaci a filtrování díky modulu <code>Enumerable</code>.</p><pre><code># Vytvoření pole\ncisla = [1, 2, 3, 4, 5]\nslova = %w[jablko hruska banan meloun]\n\n# each — iterace\ncisla.each { |c| puts c }\n\n# map — transformace (vrací nové pole)\ndvojnasobky = cisla.map { |c| c * 2 }  # [2, 4, 6, 8, 10]\n\n# select — filtrování (prvky splňující podmínku)\nsuda = cisla.select { |c| c.even? }  # [2, 4]\n\n# reject — opak select\nlicha = cisla.reject { |c| c.even? }  # [1, 3, 5]</code></pre><h2>reduce a další</h2><p><code>reduce</code> (alias <code>inject</code>) akumuluje výsledek. Je to základní nástroj pro agregace — součet, součin, hledání minima/maxima.</p><pre><code># reduce — součet\nsoucet = cisla.reduce(0) { |acc, c| acc + c }  # 15\n# Zkrácený zápis\nsoucet = cisla.reduce(:+)  # 15\n\n# reduce — hash z pole\nslova = %w[jablko hruska jablko banan jablko]\npocet = slova.reduce(Hash.new(0)) do |hash, slovo|\n  hash[slovo] += 1\n  hash\nend\n# {"jablko"=>3, "hruska"=>1, "banan"=>1}\n\n# Další užitečné metody Enumerable\n[1, 2, 3, 4].any? { |x| x > 3 }     # true\n[1, 2, 3, 4].all? { |x| x > 0 }     # true\n[1, 2, 3, 4].none? { |x| x < 0 }    # true\n[1, 2, 3, 4].find { |x| x > 2 }     # 3\n[1, 2, 3, 4].count { |x| x.even? }  # 2\n(1..10).to_a                         # [1, 2, ..., 10]\n\n# Řetězení metod (method chaining)\n(1..100).select(&:even?).map { |x| x ** 2 }.take(5)\n# [4, 16, 36, 64, 100]</code></pre><h2>Hash — slovník</h2><pre><code>osoba = { jmeno: "Karel", vek: 25, mesto: "Praha" }\n\nosoba.each { |klic, hodnota| puts "#{klic}: #{hodnota}" }\nosoba.transform_values { |v| v.to_s.upcase }\nosoba.merge(dalsi: "hodnota")\nosoba.select { |k, v| v.is_a?(String) }</code></pre>', 'lesson', 6, 15, 14),

(@kurs_id, 'Regulární výrazy', '<h2>Regulární výrazy v Ruby</h2><p>Ruby má vestavěnou plnou podporu pro regulární výrazy (regex). Zápis <code>/vzor/</code> vytvoří objekt <code>Regexp</code>. Operátor <code>=~</code> vrací pozici shody nebo <code>nil</code>.</p><pre><code># Základní shoda\n/Ahoj/ =~ "Ahoj svete"    # 0 (pozice)\n/svete/ =~ "Ahoj svete"   # 5\n/nic/ =~ "Ahoj svete"     # nil\n\n# Shoda s zachycením\nif /(\w+)@(\w+)\.(\w+)/ =~ "user@example.com"\n  puts "Uzivatel: #{$1}"  # "user"\n  puts "Domena: #{$2}"    # "example"\n  puts "TLD: #{$3}"       # "com"\nend\n\n# match — vrací MatchData objekt\nm = /(\d{4})-(\d{2})-(\d{2})/.match("2025-01-15")\nm[0]   # "2025-01-15"\nm[1]   # "2025"\nm[2]   # "01"\nm[3]   # "15"</code></pre><h2>gsub a scan</h2><p><code>gsub</code> nahrazuje všechny shody vzoru v řetězci. <code>scan</code> extrahuje všechny shody do pole.</p><pre><code># gsub — nahrazení\ntext = "Ahoj svete, ahoj vsichni"\ntext.gsub(/ahoj/i, "Cau")\n# "Cau svete, Cau vsichni"\n\n# gsub s blokem\ntext = "Cena je 100 Kc a 200 Kc"\nnove = text.gsub(/\d+/) { |cislo| cislo.to_i * 1.21 }\n# "Cena je 121 Kc a 242 Kc"\n\n# scan — extrakce shod\nemaily = "Maily: a@b.cz a x@y.com a test@test.org"\nemaily.scan(/\w+@\w+\.\w+/)  # ["a@b.cz", "x@y.com", "test@test.org"]\n\n# scan se skupinami\ntext = "Jan:25, Eva:30, Karel:22"\ntext.scan(/(\w+):(\d+)/)\n# [["Jan", "25"], ["Eva", "30"], ["Karel", "22"]]\n\n# Užitečné zkratky\n/\d/   # číslice\n/\w/   # znak slova (písmeno, číslo, _)\n/\s/   # bílý znak\n/^/    # začátek řádku\n/$/    # konec řádku</code></pre>', 'lesson', 7, 15, 13),

(@kurs_id, 'Práce se soubory', '<h2>Čtení a zápis souborů</h2><p>Ruby poskytuje třídu <code>File</code> pro operace se soubory. Vestavěné metody umožňují číst, zapisovat a manipulovat se soubory jednoduše a bezpečně.</p><pre><code># Čtení celého souboru\nobsah = File.read("data.txt")\nputs obsah\n\n# Zápis do souboru (přepíše existující)\nFile.write("vystup.txt", "Ahoj, svete!")\n\n# Připojení na konec souboru\nFile.write("log.txt", "Novy zaznam\\n", mode: "a")\n\n# Čtení po řádcích\nFile.foreach("data.txt") do |radek|\n  puts radek\nend\n\n# Blok s automatickým zavřením\nFile.open("data.txt", "r") do |f|\n  f.each_line { |radek| puts radek.chomp }\nend  # soubor se automaticky zavře\n\n# Zjištění existence a velikosti\nFile.exist?("data.txt")   # true/false\nFile.size("data.txt")     # velikost v bajtech\nFile.dirname("a/b/c.txt") # "a/b"</code></pre><h2>CSV a JSON</h2><p>Ruby má vestavěné knihovny pro práci s CSV a JSON daty. Načteš je pomocí <code>require</code>.</p><pre><code>require ''csv''\n\n# Čtení CSV\nCSV.foreach("uzivatele.csv", headers: true) do |radek|\n  puts "#{radek[''jmeno'']} - #{radek[''email'']}"\nend\n\n# Zápis CSV\nCSV.open("vystup.csv", "w") do |csv|\n  csv << ["jmeno", "email"]\n  csv << ["Karel", "karel@priklad.cz"]\n  csv << ["Eva", "eva@priklad.cz"]\nend\n\nrequire ''json''\n\n# Parsování JSON\njson_text = ''{"jmeno": "Karel", "vek": 25}''\ndata = JSON.parse(json_text)\nputs data["jmeno"]  # "Karel"\n\n# Generování JSON\nosoba = { jmeno: "Eva", vek: 30 }\nputs JSON.generate(osoba)  # {"jmeno":"Eva","vek":30}\nputs JSON.pretty_generate(osoba)  # formátovaný výstup</code></pre>', 'lesson', 8, 15, 13),

(@kurs_id, 'Rubygems a Bundler', '<h2>Rubygems</h2><p><strong>RubyGems</strong> je balíčkovací systém pro Ruby. Gem je knihovna nebo aplikace zabalená do standardizovaného formátu. Komunita Ruby vytvořila tisíce gemů pro nejrůznější účely.</p><pre><code># Instalace gemu\ngem install rails          # nainstaluje Rails\n gem install pry           # vylepšená konzole\n gem install rubocop       # linter\n\n# Vyhledávání gemů\n gem search rails\n gem list --local          # nainstalované gemy\n gem update rails          # aktualizace\n gem uninstall gem_jmeno  # odinstalace\n\n# Informace o gemu\n gem spec rails\n gem dependency rails</code></pre><h2>Bundler a Gemfile</h2><p><strong>Bundler</strong> spravuje závislosti projektu. <code>Gemfile</code> definuje, které gemy projekt potřebuje a v jakých verzích. Bundler zaručuje konzistentní prostředí napříč vývojovým týmem.</p><pre><code># Gemfile\nsource "https://rubygems.org"\n\ngem "rails", "~> 7.1"        # verze >= 7.1 a < 7.2\ngem "pg", ">= 1.5"           # PostgreSQL adapter\ngem "puma", "~> 6.0"        # webový server\ngem "devise"                 # autentizace\ngem "sidekiq"                # zpracování na pozadí\n\ngroup :development do\n  gem "pry"                  # debugger\n  gem "rubocop"              # linter\n  gem "rspec-rails"          # testy\nend\n\ngroup :production do\n  gem "scout_apm"            # monitoring\nend</code></pre><h2>Příkazy Bundleru</h2><pre><code># Instalace závislostí\nbundle install            # nainstaluje vše z Gemfile\nbundle update             # aktualizuje gemy\nbundle exec rails server  # spustí Rails v kontextu Gemfile\nbundle show rails         # cesta k gemu\nbundle outdated           # zastaralé gemy\n\n# Gemfile.lock — automaticky generovaný\n# zaručuje stejné verze na všech strojích</code></pre>', 'lesson', 9, 15, 13),

(@kurs_id, 'Úvod do Rails', '<h2>Co je Ruby on Rails?</h2><p><strong>Ruby on Rails</strong> (zkráceně Rails) je webový framework napsaný v Ruby, který vytvořil <strong>David Heinemeier Hansson</strong> v roce 2004. Rails následuje architekturu <strong>MVC</strong> (Model-View-Controller) a principy <em>Convention over Configuration</em> a <em>DRY</em> (Don''t Repeat Yourself).</p><h2>MVC architektura</h2><p><strong>Model</strong> — datová vrstva, Active Record, validace a asociace. <strong>View</strong> — prezentační vrstva, ERB šablony, HTML/CSS. <strong>Controller</strong> — řídící vrstva, zpracuje požadavek, zavolá model, vykreslí view.</p><pre><code># Vytvoření nové Rails aplikace\nrails new muj_projekt\nrails new api_app --api       # API-only režim\nrails new proj -d postgresql  # s PostgreSQL\n\ncd muj_projekt\n\n# Generátory\nrails generate model Uzivatel jmeno:string email:string vek:integer\nrails generate controller Pages home about\nrails generate scaffold Clanek titulek:string obsah:text\n\n# Databázové migrace\nrails db:create\nrails db:migrate\nrails db:seed\n\n# Spuštění serveru\nrails server   # localhost:3000\nrails s        # zkratka</code></pre><h2>Routování</h2><p>Rails routování mapuje HTTP požadavky na akce kontrolerů. Definuješ je v <code>config/routes.rb</code>.</p><pre><code># config/routes.rb\nRails.application.routes.draw do\n  # RESTful resources — vytvoří 7 akcí\n  resources :clanky\n  \n  # Vlastní routy\n  get "/o-nas", to: "pages#about"\n  get "/profil/:id", to: "uzivatele#show", as: :profil\n  \n  # Root\n  root "pages#home"\n  \n  # Nested resources\n  resources :clanky do\n    resources :komentare\n  end\nend\n\n# rails routes — vypíše všechny routy\n</code></pre>', 'lesson', 10, 15, 16),

(@kurs_id, 'Rails — modely a Active Record', '<h2>Active Record</h2><p><strong>Active Record</strong> je ORM (Object-Relational Mapping) vrstva Rails. Mapuje databázové tabulky na Ruby třídy a řádky na instance. Každý model dědí od <code>ApplicationRecord</code>.</p><pre><code># app/models/uzivatel.rb\nclass Uzivatel < ApplicationRecord\n  # Validace\n  validates :jmeno, presence: true, length: { minimum: 2 }\n  validates :email, presence: true, uniqueness: true,\n            format: { with: /\\A[\\w+-.]+@[a-z\\d-]+(\\.[a-z\\d-]+)*\\.[a-z]+\\z/i }\n  validates :vek, numericality: { only_integer: true, greater_than: 0 }\n  \n  # Asociace\n  has_many :clanky, dependent: :destroy\n  has_many :komentare\n  belongs_to :mesto, optional: true\n  has_and_belongs_to_many :role\n  \n  has_one :profil, dependent: :destroy\n  \n  # Scopes\n  scope :dospeli, -> { where("vek >= ?", 18) }\n  scope :podle_jmena, -> { order(:jmeno) }\n  scope :nedavno, ->(dny = 7) { where("created_at >= ?", dny.days.ago) }\nend</code></pre><h2>Migrace</h2><p>Migrace verzují databázové schéma. Každá migrace je soubor Ruby kódu, který popisuje změnu struktury databáze.</p><pre><code># db/migrate/20250101_create_uzivatele.rb\nclass CreateUzivatele < ActiveRecord::Migration[7.1]\n  def change\n    create_table :uzivatele do |t|\n      t.string :jmeno, null: false\n      t.string :email, null: false\n      t.integer :vek\n      t.references :mesto, foreign_key: true\n      t.timestamps  # created_at a updated_at\n    end\n    \n    add_index :uzivatele, :email, unique: true\n  end\nend\n\n# Další migrace\nrails g migration AddTelefonToUzivatele telefon:string\nrails g migration CreateClanky uzivatel:references titulek:string obsah:text\n\n# Spuštění\nrails db:migrate\nrails db:rollback    # vrátí poslední migraci</code></pre><h2>Dotazování</h2><pre><code># CRUD operace\nUzivatel.create(jmeno: "Karel", email: "karel@cz", vek: 25)\nu = Uzivatel.find(1)\nu = Uzivatel.find_by(email: "karel@cz")\nu.update(vek: 26)\nu.destroy\n\n# Dotazy\nUzivatel.where(vek: 25..35).order(:jmeno).limit(10)\nUzivatel.dospeli.podle_jmena\nUzivatel.joins(:clanky).group(:uzivatel_id).count\nUzivatel.left_joins(:clanky).where(clanky: { id: nil })</code></pre>', 'lesson', 11, 15, 18),

(@kurs_id, 'Rails — kontrolery a views', '<h2>Kontrolery</h2><p>Kontroler přijímá HTTP požadavek, zpracuje ho pomocí modelů a vykreslí view. Každý kontroler dědí od <code>ApplicationController</code>. Akce jsou veřejné metody, <code>before_action</code> spouští kód před akcí.</p><pre><code># app/controllers/clanky_controller.rb\nclass ClankyController < ApplicationController\n  before_action :najdi_clanek, only: [:show, :edit, :update, :destroy]\n  before_action :over_prihlaseni, except: [:index, :show]\n  \n  def index\n    @clanky = Clanek.podle_data.page(params[:page])\n  end\n  \n  def show\n    # @clanek nastaven before_action\n  end\n  \n  def new\n    @clanek = Clanek.new\n  end\n  \n  def create\n    @clanek = Clanek.new(clanek_params)\n    @clanek.uzivatel = current_uzivatel\n    \n    if @clanek.save\n      redirect_to @clanek, notice: "Clanek byl vytvoren."\n    else\n      render :new, status: :unprocessable_content\n    end\n  end\n  \n  private\n  \n  def najdi_clanek\n    @clanek = Clanek.find(params[:id])\n  end\n  \n  def clanek_params\n    params.require(:clanek).permit(:titulek, :obsah, :kategorie_id)\n  end\nend</code></pre><h2>Views — ERB šablony</h2><p>Rails používá <strong>ERB</strong> (Embedded Ruby) jako šablonovací systém. Tagy <code>&lt;% %&gt;</code> vykonají Ruby kód, <code>&lt;%= %&gt;</code> vypíší výsledek.</p><pre><code>&lt;!-- app/views/clanky/index.html.erb --&gt;\n&lt;h1&gt;Seznam clanku&lt;/h1&gt;\n\n&lt;% @clanky.each do |clanek| %&gt;\n  &lt;article&gt;\n    &lt;h2&gt;&lt;%= clanek.titulek %&gt;&lt;/h2&gt;\n    &lt;p&gt;&lt;%= truncate(clanek.obsah, length: 100) %&gt;&lt;/p&gt;\n    &lt;%= link_to "Cely clanek", clanek %&gt;\n  &lt;/article&gt;\n&lt;% end %&gt;\n\n&lt;!-- Partials --&gt;\n&lt;%= render partial: "clanek", collection: @clanky %&gt;\n&lt;%= render "shared/navbar" %&gt;\n&lt;%= render "form", clanek: @clanek %&gt;</code></pre><h2>Helpers</h2><p>Helpery zapouzdřují opakující se prezentační logiku. Jsou dostupné ve všech view.</p><pre><code># app/helpers/application_helper.rb\nmodule ApplicationHelper\n  def formatuj_datum(datum)\n    datum&.strftime("%d. %m. %Y") || "Neni zadano"\n  end\n  \n  def avatar_url(email, velikost = 80)\n    hash = Digest::MD5.hexdigest(email.to_s.downcase)\n    "https://www.gravatar.com/avatar/#{hash}?s=#{velikost}"\n  end\nend\n\n# Použití ve view\n&lt;%= formatuj_datum(@clanek.created_at) %&gt;\n&lt;%= image_tag avatar_url(@uzivatel.email) %&gt;</code></pre>', 'lesson', 12, 15, 16),

(@kurs_id, 'Rails — RESTful API', '<h2>API mód v Rails</h2><p>Rails může sloužit čistě jako JSON API bez view vrstvy. Vytvoříš ho parametrem <code>--api</code> nebo nastavím v <code>ApplicationController</code>.</p><pre><code># Vytvoření API-only aplikace\nrails new api_projekt --api\n\n# API kontroler dědí od ActionController::API\nclass Api::V1::UzivateleController < ActionController::API\n  def index\n    uzivatele = Uzivatel.podle_jmena\n    render json: uzivatele, each_serializer: UzivatelSerializer\n  end\n  \n  def show\n    uzivatel = Uzivatel.find(params[:id])\n    render json: uzivatel\n  end\n  \n  def create\n    uzivatel = Uzivatel.new(uzivatel_params)\n    if uzivatel.save\n      render json: uzivatel, status: :created\n    else\n      render json: { errors: uzivatel.errors },\n             status: :unprocessable_entity\n    end\n  end\n  \n  private\n  \n  def uzivatel_params\n    params.require(:uzivatel).permit(:jmeno, :email, :vek)\n  end\nend</code></pre><h2>Jbuilder a serializace</h2><p><strong>Jbuilder</strong> je defaultní nástroj pro tvorbu JSON odpovědí v Rails. Umožňuje deklarativně definovat strukturu JSON.</p><pre><code># app/views/api/v1/uzivatele/index.json.jbuilder\njson.uzivatele @uzivatele do |uzivatel|\n  json.id uzivatel.id\n  json.jmeno uzivatel.jmeno\n  json.email uzivatel.email\n  json.clanky_count uzivatel.clanky.count\n  json.url api_v1_uzivatel_url(uzivatel)\nend\n\n# Výstup:\n# {"uzivatele": [\n#   {"id":1, "jmeno":"Karel", "email":"karel@cz", "clanky_count":5, "url":"..."}\n# ]}</code></pre><h2>CORS a verzování</h2><pre><code># config/initializers/cors.rb\nRails.application.config.middleware.insert_before 0, Rack::Cors do\n  allow do\n    origins "https://muj-frontend.cz"\n    resource "/api/*",\n      headers: :any,\n      methods: [:get, :post, :put, :patch, :delete, :options]\n  end\nend\n\n# config/routes.rb — verzování API\nnamespace :api do\n  namespace :v1 do\n    resources :uzivatele\n    resources :clanky\n  end\nend\n# Routa: /api/v1/uzivatele</code></pre>', 'lesson', 13, 15, 16),

(@kurs_id, 'Rails — autentizace', '<h2>has_secure_password</h2><p>Rails nabízí vestavěnou metodu <code>has_secure_password</code>, která přidává bezpečné heslo pomocí gemu <code>bcrypt</code>. Automaticky přidává metody <code>password=</code>, <code>authenticate</code> a validaci.</p><pre><code># Gemfile\ngem "bcrypt"\n\n# app/models/uzivatel.rb\nclass Uzivatel < ApplicationRecord\n  has_secure_password\n  \n  validates :jmeno, presence: true\n  validates :email, presence: true, uniqueness: true\n  validates :password, length: { minimum: 6 },\n            format: { with: /(?=.*[A-Z])(?=.*\\d)/,\n            message: "musi obsahovat velke pismeno a cislici" }\nend\n\n# Vytvoreni uzivatele\nu = Uzivatel.create(\n  jmeno: "Karel",\n  email: "karel@cz",\n  password: "Tajne123",\n  password_confirmation: "Tajne123"\n)\n\n# Overeni hesla\nu.authenticate("spatne")   # false\nu.authenticate("Tajne123") # vrati uzivatele</code></pre><h2>Session-based autentizace</h2><p>Tradiční přístup ukládá ID uživatele do session. Rails používá cookies pro session storage.</p><pre><code># app/controllers/sessions_controller.rb\nclass SessionsController < ApplicationController\n  def create\n    uzivatel = Uzivatel.find_by(email: params[:email])\n    \n    if uzivatel&.authenticate(params[:password])\n      session[:uzivatel_id] = uzivatel.id\n      redirect_to root_path, notice: "Prihlasen!"\n    else\n      flash.now[:alert] = "Neplatne udaje"\n      render :new\n    end\n  end\n  \n  def destroy\n    session.delete(:uzivatel_id)\n    redirect_to root_path, notice: "Odhlasen!"\n  end\nend\n\n# app/controllers/application_controller.rb\nclass ApplicationController < ActionController::Base\n  helper_method :current_uzivatel\n  \n  private\n  \n  def current_uzivatel\n    @current_uzivatel ||= Uzivatel.find_by(id: session[:uzivatel_id])\n  end\n  \n  def over_prihlaseni\n    redirect_to login_path unless current_uzivatel\n  end\nend</code></pre><h2>JWT autentizace</h2><p>Pro API je často vhodnější JWT (JSON Web Token) — bezstavový přístup, vhodný pro SPA a mobilní aplikace.</p><pre><code># Gemfile\ngem "jwt"\n\n# app/lib/json_web_token.rb\nclass JsonWebToken\n  SECRET = Rails.application.credentials.secret_key_base\n  \n  def self.encode(payload, exp = 24.hours.from_now)\n    payload[:exp] = exp.to_i\n    JWT.encode(payload, SECRET)\n  end\n  \n  def self.decode(token)\n    body = JWT.decode(token, SECRET)[0]\n    HashWithIndifferentAccess.new(body)\n  rescue JWT::ExpiredSignature\n    nil\n  end\nend\n\n# V kontroleru\ndef authorize_request\n  header = request.headers["Authorization"]\n  token = header.split(" ").last if header\n  decoded = JsonWebToken.decode(token)\n  @current_uzivatel = Uzivatel.find(decoded[:uzivatel_id])\nrescue ActiveRecord::RecordNotFound\n  render json: { error: "Neopravnen" }, status: :unauthorized\nend</code></pre>', 'lesson', 14, 15, 18),

(@kurs_id, 'Rails — Active Storage', '<h2>Co je Active Storage?</h2><p><strong>Active Storage</strong> je vestavěný framework Rails pro nahrávání souborů. Podporuje lokální úložiště i cloudové služby jako Amazon S3, Google Cloud Storage a Microsoft Azure Storage.</p><pre><code># Instalace\nrails active_storage:install\nrails db:migrate\n\n# config/environments/development.rb\nconfig.active_storage.service = :local\n\n# config/environments/production.rb\nconfig.active_storage.service = :amazon</code></pre><h2>Připojení souborů k modelu</h2><p>K modelu připojíš soubory pomocí <code>has_one_attached</code> nebo <code>has_many_attached</code>. Nahrávání je asynchronní ve výrobě.</p><pre><code># app/models/uzivatel.rb\nclass Uzivatel < ApplicationRecord\n  has_one_attached :avatar\n  has_many_attached :dokumenty\n  \n  validates :avatar, content_type: ["image/png", "image/jpeg"],\n                     size: { less_than: 2.megabytes }\nend\n\n# Nahrání souboru\nu = Uzivatel.first\nu.avatar.attach(io: File.open("obrazek.jpg"),\n                filename: "obrazek.jpg",\n                content_type: "image/jpeg")\n\n# Kontrola a zobrazení\nu.avatar.attached?       # true\nu.avatar.filename        # "obrazek.jpg"\nu.avatar.content_type    # "image/jpeg"\n\n# View\n&lt;%= image_tag u.avatar %&gt;\n&lt;%= image_tag u.avatar.variant(resize_to_limit: [200, 200]) %&gt;</code></pre><h2>Varianty a transformace</h2><p>Active Storage podporuje transformace obrázků přes <strong>MiniMagick</strong> (ImageMagick) nebo <strong>Vips</strong>. Varianty se generují líně při prvním přístupu.</p><pre><code># Základní varianta\nu.avatar.variant(resize_to_limit: [300, 300])\n\n# Více variant\nu.avatar.variant(resize_to_fill: [200, 200, gravity: "Center"])\nu.avatar.variant(crop: [100, 100, 50, 50])\n\n# Preview pro PDF a video\nu.avatar.preview(resize_to_limit: [200, 200])\n\n# Konfigurace pro S3\n# config/storage.yml\namazon:\n  service: S3\n  access_key_id: &lt;%= Rails.application.credentials.dig(:aws, :access_key_id) %&gt;\n  secret_access_key: &lt;%= Rails.application.credentials.dig(:aws, :secret_access_key) %&gt;\n  region: eu-central-1\n  bucket: muj-bucket</code></pre>', 'lesson', 15, 15, 16),

(@kurs_id, 'Rails — Action Cable', '<h2>Co je Action Cable?</h2><p><strong>Action Cable</strong> je vestivěný framework Rails pro <strong>WebSockets</strong> — umožňuje obousměrnou komunikaci v reálném čase mezi serverem a klientem. Ideální pro chaty, notifikace, live updates.</p><pre><code># app/channels/application_cable/channel.rb\nmodule ApplicationCable\n  class Channel < ActionCable::Channel::Base\n  end\nend\n\n# app/channels/chat_channel.rb\nclass ChatChannel < ApplicationCable::Channel\n  def subscribed\n    stream_from "chat_#{params[:mistnost_id]}"\n  end\n  \n  def unsubscribed\n    # cleanup\n  end\n  \n  def mluv(data)\n    zprava = Zprava.create(\n      obsah: data["obsah"],\n      uzivatel: current_uzivatel,\n      mistnost_id: params[:mistnost_id]\n    )\n    \n    ActionCable.server.broadcast(\n      "chat_#{params[:mistnost_id]}",\n      {\n        obsah: zprava.obsah,\n        jmeno: zprava.uzivatel.jmeno,\n        cas: zprava.created_at.strftime("%H:%M")\n      }\n    )\n  end\nend</code></pre><h2>Klientská strana</h2><pre><code>// app/javascript/channels/chat.js\nimport consumer from "./consumer"\n\nconst chatChannel = consumer.subscriptions.create(\n  { channel: "ChatChannel", mistnost_id: 1 },\n  {\n    received(data) {\n      const chat = document.getElementById("chat-zpravy")\n      chat.insertAdjacentHTML("beforeend",\n        `&lt;div&gt;&lt;strong&gt;${data.jmeno}&lt;/strong&gt; (${data.cas}): ${data.obsah}&lt;/div&gt;`\n      )\n    },\n    speak(obsah) {\n      this.perform("mluv", { obsah })\n    }\n  }\n)\n\n// Odeslání zprávy\ndocument.querySelector("#chat-form").addEventListener("submit", (e) => {\n  e.preventDefault()\n  const input = document.querySelector("#chat-input")\n  chatChannel.speak(input.value)\n  input.value = ""\n})</code></pre><h2>Broadcasting z modelu</h2><pre><code># Automatické broadcastování po uložení\nclass Zprava < ApplicationRecord\n  belongs_to :uzivatel\n  belongs_to :mistnost\n  \n  after_create_commit do\n    broadcast_append_to(\n      [mistnost, :zpravy],\n      target: "zpravy",\n      partial: "zpravy/zprava",\n      locals: { zprava: self }\n    )\n  end\nend\n# View se aktualizuje automaticky — žádný JavaScript není potřeba!</code></pre>', 'lesson', 16, 15, 16),

(@kurs_id, 'Rails — testování', '<h2>Minitest</h2><p>Rails ve výchozím stavu používá <strong>Minitest</strong> — jednoduchý a rychlý testovací framework. Testy se nacházejí v <code>test/</code> adresáři.</p><pre><code># test/models/uzivatel_test.rb\nrequire "test_helper"\n\nclass UzivatelTest < ActiveSupport::TestCase\n  test "vytvoreni uzivatele" do\n    u = Uzivatel.new(jmeno: "Karel", email: "karel@cz", vek: 25)\n    assert u.valid?\n  end\n  \n  test "jmeno je povinne" do\n    u = Uzivatel.new(email: "test@cz")\n    assert_not u.valid?\n    assert_includes u.errors[:jmeno], "je povinne"\n  end\n  \n  test "email musi byt unikatni" do\n    Uzivatel.create!(jmeno: "A", email: "x@cz", password: "Tajne123")\n    u2 = Uzivatel.new(email: "x@cz")\n    assert_not u2.valid?\n  end\nend\n\n# test/controllers/clanky_controller_test.rb\nclass ClankyControllerTest < ActionDispatch::IntegrationTest\n  test "zobrazeni indexu" do\n    get clanky_url\n    assert_response :success\n  end\n  \n  test "vytvoreni clanku" do\n    assert_difference("Clanek.count") do\n      post clanky_url, params: { clanek: { titulek: "Test", obsah: "Obsah" } }\n    end\n  end\nend</code></pre><h2>RSpec</h2><p><strong>RSpec</strong> je populárnější alternativou s čitelnější syntaxí. Instaluje se jako gem <code>rspec-rails</code>.</p><pre><code># Gemfile\ngem "rspec-rails", group: [:development, :test]\n\n# spec/models/uzivatel_spec.rb\nrequire "rails_helper"\n\nRSpec.describe Uzivatel, type: :model do\n  it "je validni se spravnymi atributy" do\n    u = build(:uzivatel)\n    expect(u).to be_valid\n  end\n  \n  it "vyzaduje jmeno" do\n    u = build(:uzivatel, jmeno: nil)\n    expect(u).not_to be_valid\n  end\n  \n  describe "scope :dospeli" do\n    it "vraci uzivatele starsi 18 let" do\n      dospely = create(:uzivatel, vek: 25)\n      dite = create(:uzivatel, vek: 10)\n      expect(Uzivatel.dospeli).to include(dospely)\n      expect(Uzivatel.dospeli).not_to include(dite)\n    end\n  end\nend</code></pre><h2>FactoryBot</h2><p><strong>FactoryBot</strong> nahrazuje fixtures — umožňuje flexibilnější tvorbu testovacích dat.</p><pre><code># spec/factories/uzivatele.rb\nFactoryBot.define do\n  factory :uzivatel do\n    jmeno { "Karel" }\n    email { "karel#{rand(1000)}@cz" }\n    vek { 25 }\n    password { "Tajne123" }\n  end\nend\n\n# Použití\ncreate(:uzivatel)                      # uloží do DB\nbuild(:uzivatel)                       # neukládá\ncreate(:uzivatel, vek: 35)             # přepis atributu\ncreate_list(:uzivatel, 5)             # 5 uživatelů</code></pre>', 'lesson', 17, 15, 16),

(@kurs_id, 'Rails — nasazení', '<h2>Příprava na nasazení</h2><p>Před nasazením do produkce je potřeba aplikaci správně nakonfigurovat: secret key base, databáze, e-mail, asset pipeline a webový server.</p><pre><code># config/environments/production.rb\nconfig.force_ssl = true\nconfig.log_level = :info\nconfig.assets.compile = false\n\n# Secret key base\n# nastav přes ENV["SECRET_KEY_BASE"] nebo credentials\nrails credentials:edit\n\n# Databáze — PostgreSQL\n# config/database.yml\nproduction:\n  adapter: postgresql\n  encoding: unicode\n  database: muj_projekt_prod\n  pool: 25\n  host: localhost\n  username: rails\n  password: &lt;%= ENV["DB_PASSWORD"] %&gt;</code></pre><h2>Puma a Nginx</h2><p><strong>Puma</strong> je výchozí webový server pro Rails. V produkci se kombinuje s <strong>Nginx</strong> jako reverzní proxy.</p><pre><code># config/puma.rb\nworkers ENV.fetch("WEB_CONCURRENCY") { 2 }\nthreads_count = ENV.fetch("RAILS_MAX_THREADS") { 5 }\nthreads threads_count, threads_count\n\nport ENV.fetch("PORT") { 3000 }\nenvironment ENV.fetch("RAILS_ENV") { "production" }\n\n# Nginx konfigurace\n# /etc/nginx/sites-available/muj_projekt\nupstream muj_projekt {\n  server unix:///var/run/puma/muj_projekt.sock;\n}\n\nserver {\n  listen 80;\n  server_name mojedomena.cz;\n  \n  root /var/www/muj_projekt/public;\n  \n  location / {\n    proxy_pass http://muj_projekt;\n    proxy_set_header Host $host;\n    proxy_set_header X-Real-IP $remote_addr;\n  }\n  \n  location /cable {\n    proxy_pass http://muj_projekt;\n    proxy_http_version 1.1;\n    proxy_set_header Upgrade $http_upgrade;\n    proxy_set_header Connection "upgrade";\n  }\n}</code></pre><h2>Capistrano</h2><p><strong>Capistrano</strong> automatizuje nasazení na vzdálený server. Definuješ recepty v <code>deploy.rb</code>.</p><pre><code># Gemfile\ngem "capistrano", "~> 3.17", group: :development\ngem "capistrano-rails", group: :development\ngem "capistrano-rbenv", group: :development\n\n# config/deploy.rb\nset :application, "muj_projekt"\nset :repo_url, "git@github.com:user/muj_projekt.git"\nset :deploy_to, "/var/www/muj_projekt"\nset :linked_files, %w[config/database.yml .env]\nset :linked_dirs, %w[log tmp/pids tmp/cache public/uploads]\n\n# Nasazení jedním příkazem\ncap production deploy</code></pre>', 'lesson', 18, 15, 16),

(@kurs_id, 'Rails — Sidekiq a pozadí', '<h2>Active Job</h2><p><strong>Active Job</strong> je vrstva Rails pro zpracování úloh na pozadí. Abstrahuje konkrétní implementaci — můžeš přepínat mezi Sidekiq, Resque, Delayed Job a dalšími.</p><pre><code># Vytvoření jobu\nrails generate job Odeslat_email\n\n# app/jobs/odeslat_email_job.rb\nclass OdeslatEmailJob < ApplicationJob\n  queue_as :default\n  \n  # Nastavení priority\n  queue_as :urgent        # vysoká priorita\n  \n  def perform(uzivatel_id, predmet)\n    uzivatel = Uzivatel.find(uzivatel_id)\n    EmailService.odesli(uzivatel, predmet)\n  rescue ActiveRecord::RecordNotFound\n    logger.error "Uzivatel #{uzivatel_id} nenalezen"\n  end\nend\n\n# Zařazení jobu do fronty\nOdeslatEmailJob.perform_later(1, "Vitej!")\nOdeslatEmailJob.set(wait: 5.minutes).perform_later(1, "Pripominka")\nOdeslatEmailJob.set(wait_until: 1.day.from_now).perform_later(1, "Tydenni report")</code></pre><h2>Sidekiq a Redis</h2><p><strong>Sidekiq</strong> je nejpopulárnější procesor front v ekosystému Rails. Používá <strong>Redis</strong> jako úložiště front. Je rychlý, spolehlivý a podporuje konkurenci.</p><pre><code># Gemfile\ngem "sidekiq"\n\n# config/initializers/sidekiq.rb\nSidekiq.configure_server do |config|\n  config.redis = { url: ENV["REDIS_URL"] || "redis://localhost:6379/0" }\nend\n\nSidekiq.configure_client do |config|\n  config.redis = { url: ENV["REDIS_URL"] || "redis://localhost:6379/0" }\nend\n\n# config/application.rb — nastavení Active Job adapteru\nconfig.active_job.queue_adapter = :sidekiq\n\n# Sidekiq job (lepší výkon než Active Job)\nclass GenerujReportJob\n  include Sidekiq::Job\n  sidekiq_options queue: "reports", retry: 3\n  \n  def perform(report_id)\n    report = Report.find(report_id)\n    report.generuj!\n    report.odesli_emailem!\n  end\nend\n\n# Spuštění\nGenerujReportJob.perform_async(42)\nGenerujReportJob.perform_in(10.minutes, 42)</code></pre><h2>Sidekiq dashboard</h2><pre><code># config/routes.rb\nrequire "sidekiq/web"\n\nRails.application.routes.draw do\n  mount Sidekiq::Web => "/sidekiq"\n  # chráněno heslem v produkci\nend\n\n# Redis — instalace a spuštění\n# sudo apt install redis-server\n# redis-server\n# redis-cli ping  # PONG</code></pre>', 'lesson', 19, 15, 16),

(@kurs_id, 'Shrnutí — co dál s Ruby a Rails', '<h2>Co ses naučil</h2><p>Prošel jsi celou cestu od základů Ruby přes objektově orientované programování, kolekce, regulární výrazy a soubory až po kompletní Ruby on Rails — modely, kontrolery, views, API, autentizaci, Active Storage, WebSockets, testování, nasazení a zpracování na pozadí.</p><h2>Kdy zvolit Ruby/Rails</h2><p>Rails je ideální pro <strong>rychlý vývoj webových aplikací</strong> — startupy, MVP, interní nástroje, e-shopy, CRM systémy. Konvence ti umožní soustředit se na byzny logiku místo infrastruktury.</p><pre><code># Ruby — když potřebuješ:\n# - Rychlý prototyp / MVP\n# - Čitelný a udržovatelný kód\n# - Bohatý ekosystém gemů\n# - Tým, který oceňuje produktivitu\n\n# Rails je skvělý pro:\n# - CRUD-heavy aplikace\n# - SaaS platformy\n# - E-shopy a objednávkové systémy\n# - CMS a blogy\n# - API backend pro SPA/mobilní aplikace</code></pre><h2>Alternativy</h2><p>Pokud Rails je pro tvůj projekt příliš těžký, zvaž tyto alternativy:</p><pre><code># Sinatra — minimální webový framework\nrequire "sinatra"\n\nget "/hello" do\n  "Ahoj, svete!"\nend\n\n# Spustíš: ruby app.rb\n# Výhoda: jednoduchost, žádná magie\n# Nevýhoda: vše si musíš postavit sám\n\n# Hanami — "Rails, ale lépe"\n# Odlišnosti od Rails:\n# - Oddělené objekty místo monolitických modelů\n# - Explicitní návrh místo Convention over Configuration\n# - Lepší memory footprint\n# - Sucho (DRY) bez magie</code></pre><h2>Co dál studovat</h2><p>1. <strong>Hotwire</strong> — moderní frontend pro Rails (Turbo + Stimulus). 2. <strong>ViewComponent</strong> — komponentový přístup k view. 3. <strong>Dockerizace</strong> Rails aplikace. 4. <strong>GraphQL</strong> API v Rails (gem graphql-ruby). 5. <strong>Multi-tenancy</strong> — apartment gem pro SaaS. 6. <strong>Ruby 3.x</strong> — Ractor, Fiber Scheduler, pattern matching. 7. <strong>Open source</strong> — přispívej do Rails komunity.</p>', 'lesson', 20, 15, 15),

(@kurs_id, 'Závěrečný kvíz — Celý Ruby on Rails kurz', '<p>Závěrečný test pokrývající všechny lekce kurzu Ruby on Rails.</p>', 'final_quiz', 21, 200, 30);

SET @qfin = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Jaký je hlavní princip filozofie Ruby?', 'Výkon nad čitelností', 'Pravděpodobně nejlepší způsob, jak udělat programátory šťastnými', 'Kompilace za běhu', 'Statické typování', 'b', 'Matz navrhl Ruby tak, aby byl nejvíce příjemný pro programátory — čitelnost a produktivita jsou na prvním místě.', 1),
(@qfin, 'Jaký operátor se v Ruby používá pro shodu s regulárním výrazem?', '==~', '=~', '~~', '===', 'b', 'Operátor =~ vrací pozici shody (Integer) nebo nil, pokud vzor nebyl nalezen.', 2),
(@qfin, 'Co dělá klíčové slovo yield v Ruby?', 'Ukončí metodu', 'Zavolá blok předaný metodě', 'Vytvoří novou třídu', 'Definuje konstantu', 'b', 'yield spustí blok kódu, který byl metodě předán jako implicitní argument.', 3),
(@qfin, 'Jaký je rozdíl mezi Proc a lambda v Ruby?', 'Proc je rychlejší', 'Lambda kontroluje počet argumentů a return vrací z bloku, Proc nikoliv', 'Lambda neexistuje v Ruby', 'Žádný rozdíl', 'b', 'Lambda striktně kontroluje aritu argumentů a return se vrací jen z bloku. Proc aritu nekontroluje a return vrací z obklopující metody.', 4),
(@qfin, 'Co znamená MVC v kontextu Rails?', 'Model-View-Controller', 'Multiple-Variable-Configuration', 'Method-Value-Callback', 'Memory-View-Cache', 'a', 'MVC je architektura, která odděluje datovou vrstvu (Model), prezentační vrstvu (View) a řídící vrstvu (Controller).', 5),
(@qfin, 'K čemu slouží metoda has_secure_password v Rails?', 'Šifruje komunikaci', 'Přidává bezpečné ukládání a ověřování hesla pomocí bcrypt', 'Generuje CSRF token', 'Omezuje přístup k routám', 'b', 'has_secure_password přidává atributy password a password_confirmation a metodu authenticate pro bezpečné porovnání hesla pomocí bcrypt.', 6),
(@qfin, 'K čemu slouží Active Storage v Rails?', 'K ukládání session dat', 'K nahrávání a správě souborů s podporou lokálního i cloudového úložiště', 'K cachování databázových dotazů', 'K logování chyb', 'b', 'Active Storage je framework pro nahrávání souborů — podporuje lokální disk, Amazon S3, Google Cloud a Azure s variantami obrázků.', 7),
(@qfin, 'Jaký protokol používá Action Cable pro obousměrnou komunikaci v reálném čase?', 'HTTP/2', 'WebSockets', 'gRPC', 'SMTP', 'b', 'Action Cable implementuje WebSocket protokol pro obousměrnou komunikaci mezi serverem a klientem v reálném čase.', 8),
(@qfin, 'Jaký gem se používá pro zpracování úloh na pozadí v Rails s Redis?', 'Delayed Job', 'Sidekiq', 'Sneakers', 'Shoryuken', 'b', 'Sidekiq je nejpopulárnější procesor front pro Rails — používá Redis jako úložiště a podporuje konkurenci a opakování.', 9),
(@qfin, 'Co je Convention over Configuration v Rails?', 'Vše musí být explicitně nakonfigurováno', 'Rails předpokládá výchozí chování podle konvencí, takže nemusíš vše konfigurovat', 'Rails zakazuje vlastní konfiguraci', 'Každý projekt musí mít vlastní framework', 'b', 'Convention over Configuration znamená, že Rails má rozumné výchozí hodnoty — pokud dodržuješ konvence, nemusíš psát konfiguraci.', 10);


